package org.eclipse.kura.internal.rest.deployment.agent;

import java.io.IOException;

import javax.ws.rs.WebApplicationException;
import javax.ws.rs.container.ContainerRequestContext;
import javax.ws.rs.container.ContainerRequestFilter;
import javax.ws.rs.container.ContainerResponseContext;
import javax.ws.rs.container.ContainerResponseFilter;
import javax.ws.rs.core.HttpHeaders;
import javax.ws.rs.core.Response;
import javax.ws.rs.core.Response.Status;
import javax.ws.rs.ext.Provider;

import org.apache.commons.io.input.BoundedInputStream;
import org.eclipse.kura.system.SystemService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Provider
@LimitMultipartRequestEntitySize
public class MultipartRequestBodySizeLimiter implements ContainerRequestFilter, ContainerResponseFilter {

    private static final String FILE_TRANSFER_SIZE_MAX_PROP_NAME = "file.transfer.size.max";
    private static final String ENTITY_TOO_LARGE_PROPERTY = MultipartRequestBodySizeLimiter.class.getName()
            + ".entityTooLarge";
    private static final Logger logger = LoggerFactory.getLogger(MultipartRequestBodySizeLimiter.class);

    private long limit = 25 * 1024 * 1024;

    public void setSystemService(final SystemService systemService) {
        final String limitString = systemService.getProperties().getProperty(FILE_TRANSFER_SIZE_MAX_PROP_NAME);

        try {
            if (limitString != null) {
                this.limit = Long.parseLong(limitString);
            }
        } catch (final Exception e) {
            logger.warn("failed to parse {} property", FILE_TRANSFER_SIZE_MAX_PROP_NAME, e);
        }
    }

    @Override
    public void filter(ContainerRequestContext context) throws IOException {
        final String contentLength = context.getHeaders().getFirst(HttpHeaders.CONTENT_LENGTH);

        if (contentLength != null && isTooLarge(contentLength)) {
            throw new WebApplicationException(buildEntityTooLargeResponse());
        }

        if (limit >= 0) {
            final BoundedInputStream bounded = BoundedInputStream.builder().setMaxCount(this.limit + 1)
                    .setInputStream(context.getEntityStream()).setOnMaxCount((c, l) -> {
                        // An IOException is needed to let the multipart parser release its temporary files, the
                        // response filter will then replace the resulting error status with 413.
                        context.setProperty(ENTITY_TOO_LARGE_PROPERTY, Boolean.TRUE);
                        throw new IOException("Entity too large");
                    }).get();

            context.setEntityStream(bounded);
        }
    }

    @Override
    public void filter(ContainerRequestContext requestContext, ContainerResponseContext responseContext)
            throws IOException {
        if (requestContext.getProperty(ENTITY_TOO_LARGE_PROPERTY) != null) {
            responseContext.setStatus(Status.REQUEST_ENTITY_TOO_LARGE.getStatusCode());
            responseContext.setEntity(null);
            responseContext.getHeaders().putSingle("Connection", "close");
        }
    }

    private static Response buildEntityTooLargeResponse() {
        return Response.status(Status.REQUEST_ENTITY_TOO_LARGE).header("Connection", "close").build();
    }

    private boolean isTooLarge(final String contentLength) {
        try {
            return this.limit >= 0 && Long.parseLong(contentLength.trim()) > this.limit;
        } catch (final NumberFormatException e) {
            return false;
        }
    }

}
